//! Generated by generate_gates.py from gates/gate_recipes.toml — edit the recipe, not this file.
//! The CLI face against the CLI contract (`MUST_READ_BEFORE_BUILDING.md` § Approved interfaces).
//! Success needs a real examples-reduced file; it is shown against the pipeline's own data at deploy.

use std::error::Error;
use std::fs;
use std::process::{Command, Output};

type TestResult = Result<(), Box<dyn Error>>;

fn run(args: &[&str]) -> Result<Output, Box<dyn Error>> {
    Ok(Command::new(env!("CARGO_BIN_EXE_gate_examples_reduced_input")).args(args).output()?)
}

#[test]
fn a_missing_file_is_a_read_error_on_stderr_and_exits_1() -> TestResult {
    let output = run(&["/absolutely/does/not/exist.toml"])?;

    assert_eq!(output.status.code(), Some(1));
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(stderr.lines().next(), Some("read_error"));
    Ok(())
}

#[test]
fn a_file_that_does_not_match_the_schema_is_a_validation_error_and_exits_1() -> TestResult {
    let file = std::env::temp_dir().join(format!("gate_examples_reduced_input_invalid_{}.toml", std::process::id()));
    fs::write(&file, "not_a_field_of_this_schema = 1\n")?;
    let output = run(&[file.to_str().ok_or("fixture path is not UTF-8")?])?;

    assert_eq!(output.status.code(), Some(1));
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr)?;
    assert_eq!(stderr.lines().next(), Some("validation_error"));
    Ok(())
}

#[test]
fn wrong_arguments_print_the_usage_and_exit_2() -> TestResult {
    let output = run(&[])?;

    assert_eq!(output.status.code(), Some(2));
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr)?;
    assert!(stderr.starts_with("usage: gate_examples_reduced_input"));
    Ok(())
}
